import{c as i,ah as s,L as a,O as l}from"./chunks/framework.YKVbmyBD.js";const k=JSON.parse('{"title":"认识命令行","description":"","frontmatter":{},"headers":[],"relativePath":"fovlin-notes/linux-guide/cli-guide.md","filePath":"fovlin-notes/linux-guide/cli-guide.md"}'),d={name:"fovlin-notes/linux-guide/cli-guide.md"};function h(t,e,o,c,n,p){return s(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="认识命令行" tabindex="-1">认识命令行 <a class="header-anchor" href="#认识命令行" aria-label="Permalink to “认识命令行”">​</a></h1><blockquote><p>命令行是 Linux 的精髓，它可以快速帮助你完成你想要操作系统执行的动作。</p></blockquote><blockquote><p>特别在服务器系统中，为了保持轻量化，并不会预装图形化界面，因此无论你是否要安装图形化界面，必须先通过命令行控制主机。</p></blockquote><h2 id="进入命令行" tabindex="-1">进入命令行 <a class="header-anchor" href="#进入命令行" aria-label="Permalink to “进入命令行”">​</a></h2><p>若没有安装桌面环境，或并未启用登录管理器，默认开机进入系统时，会进入 <code>tty</code> 窗口，即整个主机的终端，可以通过 <code>Ctrl</code> + <code>F1 ~ F6</code> 中任意一个按键来进入终端，<code>F1 ~ F6</code> 分别对应 <code>tty1</code> ~ <code>tty6</code> 6 个不同的会话，这些会话相互独立，可以运行多个不同的任务。</p><p>在预装了桌面环境的发行版中，查找终端字样的应用程序，打开即可进入终端，但这并非实际意义上的终端，仅仅是运行在桌面环境中的终端模拟器，通过模拟器可以操控命令行控制系统。</p><p>如果桌面出现故障，无法进行任何操作，也可以通过 <code>Ctrl</code> + <code>F1 ~ F6</code> 来进入 <code>tty</code> 终端，进行排错。</p><p>一般来说，使用 <code>tty</code> 需要先进行登录，输入用户名，回车后输入密码，即可进入 <code>tty</code>，但要注意的是，密码在输入过程中并不可见，这并不是键盘故障，而是出于安全考虑有意为之。</p><h2 id="shell" tabindex="-1">Shell <a class="header-anchor" href="#shell" aria-label="Permalink to “Shell”">​</a></h2><p>用户在终端，输入的命令将会通过 <code>shell</code> 解释并传递给系统，同时 <code>shell</code> 也会分为不同的几种，常见的 <code>shell</code> 有 <code>bash</code> <code>zsh</code> <code>fish</code> <code>sh</code>，其中 <code>bash</code> 以出色语法兼容性被广泛内置于绝大多数的发行版中。</p><p>同样地，如果你安装了其他的 <code>shell</code>，可以直接使用他们的名称作为命令调用不同的 <code>shell</code>，这是暂时性的，若要更改当前用户的默认 <code>shell</code>，使用 <code>chsh -s</code> 命令进行更改，后接 <code>shell</code> 二进制文件的绝对路径，通常被存放于 <code>/bin</code> 路径下，如更改为 <code>bash</code> 如下：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /bin/bash</span></span></code></pre></div><h2 id="工作目录" tabindex="-1">工作目录 <a class="header-anchor" href="#工作目录" aria-label="Permalink to “工作目录”">​</a></h2><p>工作目录是当前命令行所在的目录位置，借助工作目录配合后续命令使用，工作效率将大幅提高。</p><p>登入终端的位置默认为用户的家目录，你可以通过 <code>pwd</code> 命令来查看自己当前所处的文件夹，结果将返回一个路径，为当前所在的路径。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span></span></code></pre></div><p>一个示例输出如下，表示你当前处于 <code>/home/fovlin</code> 目录下。</p><div class="language-log"><button title="Copy Code" class="copy"></button><span class="lang">log</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/home/fovlin</span></span></code></pre></div><p><code>cd</code> 命令可以更改当前的工作目录，传入的参数既可以是相对路径也可以是绝对路径，例如前往当前目录下的 <code>/home/fovlin/documents</code> 目录：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /home/fovlin/documents</span></span></code></pre></div><h2 id="path-变量" tabindex="-1">$PATH 变量 <a class="header-anchor" href="#path-变量" aria-label="Permalink to “$PATH 变量”">​</a></h2><p><code>$PATH</code> 是一个变量，包含着数个目录路径，每个路径之间使用 <code>:</code> 进行连接。</p><p>一个系统中的 <code>$PATH</code> 变量至少包含以下路径：</p><div class="language-log"><button title="Copy Code" class="copy"></button><span class="lang">log</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/usr/local/sbin:/usr/local/bin:/usr/bin</span></span></code></pre></div><p>当在命令行输入命令并回车时候，<code>shell</code> 会查询 <code>$PATH</code> 包含的每个路径下的二进制文件，顺序为从左到右，左侧优先级更高，如果查询到与输入命令的相同名称的可执行文件，将会直接调用该二进制文件，如果命令后有以空格为分隔其他字段，将会被作为参数传入二进制可执行文件。</p><h2 id="运行可执行程序" tabindex="-1">运行可执行程序 <a class="header-anchor" href="#运行可执行程序" aria-label="Permalink to “运行可执行程序”">​</a></h2><p>直接键入命令将运行 <code>$PATH</code> 变量路径下的可执行文件。</p><p>而想要运行不在该变量中的可执行文件，可以使用绝对路径，或者相对路径。</p><p>使用绝对路径，例如一个可执行文件位于 <code>/usr/local/nginx/sbin/nginx</code> 路径，要运行 <code>nginx</code> 这个程序，在命令行输入该文件的绝对路径：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/usr/local/nginx/sbin/nginx</span></span></code></pre></div><p>如当前目录下的 <code>code</code> 文件，如下：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./code</span></span></code></pre></div><blockquote><p>若提示权限拒绝，表示该文件并没有可执行权限，使用 <code>chmod 711 &lt;filename&gt;</code>，为文件添加可执行权限。</p></blockquote><p>对于传入参数为路径的，当前工作目录下的文件可以直接填写文件名称以表示当前目录下的文件，例如以当前目录下的 <code>dir</code> 目录为传入参数：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dir</span></span></code></pre></div><p>等效于 <code>cd ./dir</code>。</p><h2 id="自动补全" tabindex="-1">自动补全 <a class="header-anchor" href="#自动补全" aria-label="Permalink to “自动补全”">​</a></h2><p>手敲长命令是一种非常不友好的行为，shell 能在接受到 <code>Tab</code> 键信号后，自动预测该命令可能支持的下一个可填充字段，当有多个可填充字段出现，连续按两次 <code>Tab</code>，可列出所有可填充字段，当命令输入到一半，且后续没有其他可用字段与之匹配时候，使用 <code>Tab</code> 键补全是一个显著提高效率的操作。</p><h2 id="管道" tabindex="-1">管道 <a class="header-anchor" href="#管道" aria-label="Permalink to “管道”">​</a></h2><p>在命令行中，<code>|</code> 可以被加在执行命令后方，并后接其他命令，该符号被称为管道，管道前命令产生的输出会被管道输入到后方的命令，并进行执行。</p><p>一个简单的例子是查找一个目录下的一个文件，使用 <code>ls</code> 命令产生输出，并通过管道输入到后方的 <code>grep</code> 查找命令中，<code>grep</code> 命令将列出包含查找字符串的所有行。</p><p>例如查找包含 <code>file</code> 字符串的文件及其文件夹：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lah</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file</span></span></code></pre></div>',43)])])}const g=i(d,[["render",h]]);export{k as __pageData,g as default};
